package com.bank.inherit.service;

import com.bank.inherit.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Slf4j
public class AccountReportService {

    @PersistenceContext
    private EntityManager em;

    // Same JPQL, DIFFERENT generated SQL depending on the strategy:
    //  SINGLE_TABLE    → select ... from accounts (no join)
    //  JOINED          → select ... from account_base left join savings_account
    //                    left join current_account (joins)
    //  TABLE_PER_CLASS → select ... from (savings_full UNION ALL current_full)
    @Transactional(readOnly = true)
    public int polymorphicCount() {
        List<Account> all = em.createQuery("select a from Account a", Account.class)
                              .getResultList();
        log.info("Polymorphic query returned {} accounts (SQL shape depends on strategy)",
                all.size());
        return all.size();
    }
}
